const variants={"overview":View0};
export interface ArtemisStatusPagesProps { className?: string; variant?: "overview"; }
export function ArtemisStatusPages({className,variant="overview"}:ArtemisStatusPagesProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import type { HTMLAttributes } from "react";
import { ArtemisValidationFrame } from "../../../../lib/validation-frame";
export function Field({className,...props}:HTMLAttributes<HTMLDivElement>&{error:boolean}){return <ArtemisValidationFrame {...props} finishShakeOnClear focusBorder="art:border-muted-foreground/40" className={className?.replace(/art:border-border$/,'')}/>;}

"use client";
// @zeus-internal
import { motion, useReducedMotion, type HTMLMotionProps } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
const hidden = { opacity: 0, transform: "translateY(16px)", filter: "blur(6px)" };
const shown = { opacity: 1, transform: "translateY(0px)", filter: "blur(0px)" };
export function Reveal({ as, delay = 0, children, ...props }: Omit<HTMLMotionProps<"header">, "ref"> & {
    as: "header" | "section";
    delay?: number;
}) {
    const reduce = useReducedMotion();
    const Component = as === "header" ? motion.header : motion.section;
    return <Component {...props} data-status-overview-reveal="" initial={reduce ? { opacity: 1, transform: "none", filter: "none" } : hidden} whileInView={shown} viewport={{ once: true, amount: 0.15 }} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay }}>{children}</Component>;
}

// @zeus-internal
export { ArtemisStateButton as StatefulButton } from "../../../../lib/state-button";
export type { ArtemisButtonState as ButtonState, ArtemisStateButtonProps as StatefulButtonProps } from "../../../../lib/state-button";

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion, type HTMLMotionProps } from "motion/react";
import { Check, LoaderCircle, X } from "lucide-react";
import { forwardRef, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { ArtemisButton } from "../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_SWAP } from "./ease";
export type ArtemisButtonState = "idle" | "loading" | "success" | "error";
export interface ArtemisStateButtonProps extends Omit<HTMLMotionProps<"button">, "children"> {
  state?: ArtemisButtonState;
  children: ReactNode;
  loadingText?: ReactNode;
  successText?: ReactNode;
  errorText?: ReactNode;
  icon?: ReactNode;
}
export const ArtemisStateButton = forwardRef<HTMLButtonElement, ArtemisStateButtonProps>(function ArtemisStateButton({ state = "idle", children, loadingText = "Loading", successText = "Done", errorText = "Try again", icon, className = "", disabled, ...props }, ref) {
  const reduced = useReducedMotion() === true;
  const measure = useRef<HTMLSpanElement>(null);
  const [labelWidth, setLabelWidth] = useState<number>();
  const label = state === "loading" ? loadingText : state === "success" ? successText : state === "error" ? errorText : children;
  const Icon = state === "loading" ? LoaderCircle : state === "success" ? Check : state === "error" ? X : null;
  const visualIcon = Icon ? <Icon className={state === "loading" ? "art:size-4 art:animate-spin art:motion-reduce:animate-none" : "art:size-4"}/> : icon;
  useLayoutEffect(() => {
    const element = measure.current;
    if (!element) return;
    const update = () => setLabelWidth(element.getBoundingClientRect().width);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => observer.disconnect();
  }, [label]);
  return <ArtemisButton {...props} ref={ref} className={`art:relative ${className} art:gap-0`} whileHover={props.whileHover} whileTap={props.whileTap} disabled={disabled || state === "loading"} aria-busy={state === "loading"}>
    <span className="art:sr-only">{label}</span>
    <span ref={measure} aria-hidden="true" className="art:pointer-events-none art:invisible art:absolute art:whitespace-pre">{label}</span>
    <AnimatePresence initial={false} mode="popLayout">{visualIcon && <motion.span key={state} aria-hidden="true" className="art:flex art:shrink-0 art:items-center art:justify-center art:overflow-hidden" initial={{ width: 0, opacity: 0, scale: 0.7, filter: "blur(6px)" }} animate={{ width: 24, opacity: 1, scale: 1, filter: "blur(0px)" }} exit={{ width: 0, opacity: 0, scale: 0.7, filter: "blur(6px)" }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_SWAP}>{visualIcon}</motion.span>}</AnimatePresence>
    <motion.span aria-hidden="true" className="art:relative art:inline-flex art:whitespace-nowrap" animate={{ width: labelWidth }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_SWAP}>
      <AnimatePresence initial={false} mode="popLayout"><motion.span key={state} className="art:inline-flex" initial={false}>
        {typeof label === "string" ? Array.from(label, (character, index) => <motion.span key={index} className="art:inline-block" initial={reduced ? false : { opacity: 0, y: "105%", filter: "blur(6px)" }} animate={{ opacity: 1, y: "0%", filter: "blur(0px)" }} exit={reduced ? { opacity: 0 } : { opacity: 0, y: "-105%", filter: "blur(6px)", transition: { duration: 0.16, delay: index * 0.0125, ease: ARTEMIS_EASE_OUT } }} transition={reduced ? { duration: 0 } : { ...ARTEMIS_SPRING_SWAP, delay: index * 0.025 }}>{character === " " ? "\u00a0" : character}</motion.span>) : label}
      </motion.span></AnimatePresence>
    </motion.span>
  </ArtemisButton>;
});

"use client";
// @zeus-internal
import { animate, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState, type HTMLAttributes } from "react";
export interface ArtemisValidationFrameProps extends HTMLAttributes<HTMLDivElement> {
    error?: boolean;
    focused?: boolean;
    focusBorder?: string;
    finishShakeOnClear?: boolean;
}
export function ArtemisValidationFrame({ error = false, focused: controlled, focusBorder = "art:border-foreground/60", finishShakeOnClear = true, className = "", children, onFocus, onBlur, ...props }: ArtemisValidationFrameProps) {
    const [focus, setFocus] = useState(false);
    const ref = useRef<HTMLDivElement>(null);
    const reduce = useReducedMotion();
    const playbackRef = useRef<{
        stop: () => void;
    } | null>(null);
    useEffect(() => () => playbackRef.current?.stop(), []);
    const focused = controlled ?? focus;
    useEffect(() => {
        const element = ref.current;
        if (!element || !error || reduce) {
            if (element && (reduce || !finishShakeOnClear)) {
                playbackRef.current?.stop();
                playbackRef.current = null;
                element.style.transform = "none";
                element.style.translate = "none";
            }
            return;
        }
        playbackRef.current?.stop();
        const playback = animate(element, { x: [0, -6, 6, -4, 4, -2, 0] }, { duration: 0.45 });
        playbackRef.current = playback;
        return () => { if (!finishShakeOnClear) {
            playback.stop();
            if (playbackRef.current === playback)
                playbackRef.current = null;
        } };
    }, [error, reduce, finishShakeOnClear]);
    const border = error ? "art:border-destructive" : focused ? focusBorder : "art:border-border";
    return <div {...props} ref={ref} data-state={error ? "error" : focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${border} ${className}`} onFocus={event => { setFocus(true); onFocus?.(event); }} onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget))
        setFocus(false); onBlur?.(event); }}>{children}</div>;
}
